			text = [=[Overlord Mok'Morokk rules the {red:stonemaul-ogres}Stonemaul ogres{/red} from {link:brackenwall-village}Brackenwall Village{/link}. {link:rexxar}Rexxar{/link} made him overlord, and Mok'Morokk never lets anyone forget it. When black dragons burned the Stonemaul village in the south, he led his people north to the reeds. He calls that wisdom. Many of his ogres call it running.]=],
		},
		{
			title = "Significance",
			text = [=[Mok'Morokk shows what power can do to a leader who is not watched. He was strong while {link:rexxar}Rexxar{/link} led the clan. After Rexxar left, he began to demand service instead of giving it, and his people began to turn against him.]=],
		},
		{
			title = "Deeds",
			text = [=[• He led the Stonemaul out of their old village when the black dragons came.
• He sent others back to the ruins for the grog, snuff and strongbox he left behind.
• He refused to take up arms against the brood of {link:onyxia}Onyxia{/link}.]=],
		},
	},
	chapters = {
		{
